In what order does this program print its lines, first to last?

```go
func main() {
	done := make(chan struct{})
	go func() {
		defer close(done)
		defer fmt.Println("outer deferred")
		func() {
			defer fmt.Println("inner deferred")
			fmt.Println("calling Goexit")
			runtime.Goexit()
		}()
		fmt.Println("unreachable")
	}()
	<-done
	fmt.Println("main resumes")
}
```

